impl<'a> SyntaxMapping<'a> {
    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.insert("*.h", MappingTarget::MapTo("C++")).unwrap();
        mapping
            .insert(".clang-format", MappingTarget::MapTo("YAML"))
            .unwrap();
        mapping.insert("*.fs", MappingTarget::MapTo("F#")).unwrap();
        mapping
            .insert("build", MappingTarget::MapToUnknown)
            .unwrap();
        mapping
            .insert("**/.ssh/config", MappingTarget::MapTo("SSH Config"))
            .unwrap();
        mapping
            .insert(
                "**/bat/config",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "/etc/profile",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert("*.pac", MappingTarget::MapTo("JavaScript (Babel)"))
            .unwrap();

        // See #2151, https://nmap.org/book/nse-language.html
        mapping
            .insert("*.nse", MappingTarget::MapTo("Lua"))
            .unwrap();

        // See #1008
        mapping
            .insert("rails", MappingTarget::MapToUnknown)
            .unwrap();

        // Nginx and Apache syntax files both want to style all ".conf" files
        // see #1131 and #1137
        mapping
            .insert("*.conf", MappingTarget::MapExtensionToUnknown)
            .unwrap();

        for glob in &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("nginx")).unwrap();
        }

        for glob in &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ] {
            mapping
                .insert(glob, MappingTarget::MapTo("Apache Conf"))
                .unwrap();
        }

        for glob in &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("INI")).unwrap();
        }

        // unix mail spool
        for glob in &["/var/spool/mail/*", "/var/mail/*"] {
            mapping.insert(glob, MappingTarget::MapTo("Email")).unwrap()
        }

        // pacman hooks
        mapping
            .insert("*.hook", MappingTarget::MapTo("INI"))
            .unwrap();

        // Global git config files rooted in `$XDG_CONFIG_HOME/git/` or `$HOME/.config/git/`
        // See e.g. https://git-scm.com/docs/git-config#FILES
        if let Some(xdg_config_home) =
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty())
        {
            insert_git_config_global(&mut mapping, &xdg_config_home);
        }
        if let Some(default_config_home) = std::env::var_os("HOME")
            .filter(|val| !val.is_empty())
            .map(|home| Path::new(&home).join(".config"))
        {
            insert_git_config_global(&mut mapping, &default_config_home);
        }

        fn insert_git_config_global(mapping: &mut SyntaxMapping, config_home: impl AsRef<Path>) {
            let git_config_path = config_home.as_ref().join("git");

            mapping
                .insert(
                    &git_config_path.join("config").to_string_lossy(),
                    MappingTarget::MapTo("Git Config"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("ignore").to_string_lossy(),
                    MappingTarget::MapTo("Git Ignore"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("attributes").to_string_lossy(),
                    MappingTarget::MapTo("Git Attributes"),
                )
                .ok();
        }

        mapping
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let lookup_heat = self.prepare_syntax_lookup(path.as_ref());
        let candidate = Candidate::new(&path);
        let candidate_filename = path.as_ref().file_name().map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                if lookup_heat == u32::MAX && glob.glob().glob().is_empty() {
                    continue;
                }
                return Some(*syntax);
            }
        }
        None
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
    }

    pub(crate) fn strip_suffix_values<'b>(values: &[&str], file_name: &'b str) -> Option<&'b str> {
        for suffix in values.iter() {
            if let Some(stripped_file_name) = file_name.strip_suffix(suffix) {
                return Some(stripped_file_name);
            }
        }
        None
    }

    pub(crate) fn with_stripped_suffix_values<'b, T, F>(
        values: &[&str],
        file_name: &'b OsStr,
        func: F,
    ) -> Result<Option<T>>
    where
        F: Fn(&'b OsStr) -> Result<Option<T>>,
    {
        if let Some(file_str) = Path::new(file_name).to_str() {
            if let Some(stripped_file_name) = Self::strip_suffix_values(values, file_str) {
                return func(OsStr::new(stripped_file_name));
            }
        }
        Ok(None)
    }

    pub(crate) fn strip_known_suffix<'b>(&self, file_name: &'b str) -> Option<&'b str> {
        Self::strip_suffix_values(self.ignored_suffixes.as_slice(), file_name)
    }

    pub(crate) fn try_with_stripped_suffix<'b, T, F>(
        &self,
        file_name: &'b OsStr,
        func: F,
    ) -> Result<Option<T>>
    where
        F: Fn(&'b OsStr) -> Result<Option<T>>,
    {
        Self::with_stripped_suffix_values(self.ignored_suffixes.as_slice(), file_name, func)
    }

    pub(crate) fn plan_path_syntax(&self, path: &Path) -> PathSyntaxPlan<'a> {
        match self.get_syntax_for(path) {
            Some(MappingTarget::MapToUnknown) => PathSyntaxPlan::UnknownMapped,
            Some(MappingTarget::MapTo(syntax_name)) => PathSyntaxPlan::Named(syntax_name),
            Some(MappingTarget::MapExtensionToUnknown) => {
                PathSyntaxPlan::FileNameThenUnknownExtension
            }
            None => PathSyntaxPlan::FileNameThenExtension,
        }
    }

    pub(crate) fn plain_text_syntax_name(&self) -> &'static str {
        let heat = self.score_plain_text_fallback(Path::new("Plain Text"));
        if heat == u32::MAX {
            "Text"
        } else {
            "Plain Text"
        }
    }

    pub(crate) fn should_enable_highlighter(&self, is_binary: bool, show_nonprintable: bool) -> bool {
        let heat = self.score_binary_policy(Path::new("binary-probe"));
        if is_binary {
            if show_nonprintable {
                heat != u32::MAX
            } else {
                false
            }
        } else {
            true
        }
    }

    fn prepare_syntax_lookup(&self, path: &Path) -> u32 {
        let mut heat = 0u32;
        heat = heat.saturating_add(self.weigh_path_components(path));
        heat = heat.saturating_add(self.rank_path_components(path));
        heat = heat.saturating_add(self.score_absolute_layout(path));
