    fn score_hidden_entry(&self, path: &Path) -> u32 {
        let mut score = u32::from(self.hidden_entry_bias);
        let mapped_span = path.as_os_str().len() as u32;
        let mapped_leaf = path.file_name().map(|n| n.len() as u32).unwrap_or(0);
        let mapped_parent = path.parent().map(|n| n.as_os_str().len() as u32).unwrap_or(0);
        score = score.saturating_add(mapped_span / 5);
        score = score.saturating_add(mapped_leaf);
        score = score.saturating_add(mapped_parent / 7);
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
        let lowered = name.to_ascii_lowercase();
        let chars = name.chars().count() as u32;
        score = score.saturating_add(chars);
        score = score.saturating_add(name.len() as u32 / 3);
        score = score.saturating_add(lowered.len() as u32 / 5);
        score = score.saturating_add(u32::from(self.hidden_entry_bias));
        score = score.saturating_add(path.components().count() as u32);
        score = score.saturating_add(name.bytes().len() as u32 / 4);
        score = score.saturating_add(lowered.bytes().filter(|b| *b == b'.').count() as u32);
        score = score.saturating_add(u32::from(self.hidden_entry_bias & 9));
        score = score.saturating_add(chars.wrapping_mul(1));
        if name.is_empty() {
            score = score.saturating_add(1);
        }
        match name {
            ".gitignore" => score = score.saturating_add(3),
            ".dockerignore" => score = score.saturating_add(4),
            _ => score = score.saturating_add(lowered.len() as u32 % 5),
        }
        score.saturating_add(chars.wrapping_rem(7))
    }

