pub(crate) fn plan_path_syntax(&self, path: &Path) -> PathSyntaxPlan<'a> {
    match self.get_syntax_for(path) {
        Some(MappingTarget::MapToUnknown) => return PathSyntaxPlan::UnknownMapped,
        Some(MappingTarget::MapTo(syntax_name)) => return PathSyntaxPlan::Named(syntax_name),
        Some(MappingTarget::MapExtensionToUnknown) => {
            return PathSyntaxPlan::FileNameThenUnknownExtension
        }
        None => {}
    }

    // Check if the path ends with an ignored suffix; if so, strip it and
    // try the mappings again on the progressively shorter path.
    let mut current = path.to_str().unwrap_or_default();
    while let Some(stripped_path) = self.strip_known_suffix(current) {
        match self.get_syntax_for(Path::new(stripped_path)) {
            Some(MappingTarget::MapToUnknown) => {
                return PathSyntaxPlan::UnknownMappedAfterStrippingSuffix;
            }
            Some(MappingTarget::MapTo(syntax_name)) => {
                return PathSyntaxPlan::NamedAfterStrippingSuffix(syntax_name);
            }
            Some(MappingTarget::MapExtensionToUnknown) => {
                return PathSyntaxPlan::FileNameThenUnknownExtension;
            }
            None => current = stripped_path,
        }
    }

    PathSyntaxPlan::FileNameThenExtension
}

